// What: finds every compiled test file instead of keeping a hand-written list.
// Why: a new test file used to be skipped silently until someone remembered to add it
//      to `package.json` (BUG-30). Discovery makes the file system the source of truth.
// Removed: `npm test` would go back to running only the files listed by hand.
import { existsSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';

export const TEST_ROOTS = [
  { directory: 'dist-electron', extension: '.test.js' },
  { directory: 'dist-renderer-test', extension: '.test.js' },
  { directory: 'scripts', extension: '.test.mjs' },
];

function walk(directory, extension, found) {
  for (const name of readdirSync(directory).sort()) {
    const full = path.join(directory, name);
    if (statSync(full).isDirectory()) {
      walk(full, extension, found);
    } else if (name.endsWith(extension)) {
      found.push(full);
    }
  }
}

export function discoverTestFiles(baseDirectory, roots = TEST_ROOTS) {
  const found = new Set();
  for (const { directory, extension } of roots) {
    const root = path.join(baseDirectory, directory);
    if (!existsSync(root)) {
      throw new Error(
        `Test root ${directory} is missing. Run the TypeScript build before the tests.`,
      );
    }
    walk(root, extension, []);
    const files = [];
    walk(root, extension, files);
    for (const file of files) found.add(path.resolve(file));
  }
  return [...found].sort();
}

// What: the single test entry point. It discovers every compiled test, runs it, and reports how
//      many files actually executed.
// Why: BUG-30 was a hand-written file list that silently skipped new tests. The count check also
//      catches a compiled file that registers no tests, which would otherwise look like success.
// Removed: `npm test` would run only named files and could pass while skipping suites.
import path from 'node:path';
import { run } from 'node:test';
import { spec } from 'node:test/reporters';
import { discoverTestFiles } from './test-files.mjs';

const files = discoverTestFiles(process.cwd());
console.log(`Discovered ${files.length} test files.`);
if (files.length === 0) {
  console.error('No test files were found. The TypeScript build did not produce any.');
  process.exit(1);
}

const seenFiles = new Set();
let failures = 0;

const stream = run({ files });
stream.on('data', (event) => {
  const file = event.data?.file;
  if (file) seenFiles.add(path.resolve(file));
  if (event.type === 'test:fail') failures += 1;
});
stream.on('end', () => {
  const missing = files.filter((file) => !seenFiles.has(file));
  console.log(`Ran ${seenFiles.size} of ${files.length} test files.`);
  if (missing.length > 0) {
    console.error('Test files that registered no tests:');
    for (const file of missing) console.error(`  ${file}`);
    process.exitCode = 1;
  }
  if (failures > 0) process.exitCode = 1;
});
stream.compose(new spec()).pipe(process.stdout);

import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { after, describe, it } from 'node:test';
import { discoverTestFiles } from './test-files.mjs';

describe('discoverTestFiles', () => {
  const base = mkdtempSync(path.join(os.tmpdir(), 'chesspulse-test-files-'));
  after(() => rmSync(base, { recursive: true, force: true }));

  it('finds nested tests under every root and ignores other files', () => {
    mkdirSync(path.join(base, 'dist-electron', 'main', 'analysis'), { recursive: true });
    mkdirSync(path.join(base, 'dist-renderer-test', 'renderer'), { recursive: true });
    mkdirSync(path.join(base, 'scripts'), { recursive: true });
    writeFileSync(path.join(base, 'dist-electron', 'main', 'analysis', 'pgn.test.js'), '');
    writeFileSync(path.join(base, 'dist-electron', 'main', 'helpers.js'), '');
    writeFileSync(path.join(base, 'dist-renderer-test', 'renderer', 'Review.test.js'), '');
    writeFileSync(path.join(base, 'scripts', 'copy-check.test.mjs'), '');
    writeFileSync(path.join(base, 'scripts', 'copy-check.mjs'), '');

    assert.deepEqual(discoverTestFiles(base), [
      path.join(base, 'dist-electron', 'main', 'analysis', 'pgn.test.js'),
      path.join(base, 'dist-renderer-test', 'renderer', 'Review.test.js'),
      path.join(base, 'scripts', 'copy-check.test.mjs'),
    ]);
  });

  it('fails loudly when a compiled root is missing', () => {
    assert.throws(
      () => discoverTestFiles(base, [{ directory: 'dist-missing', extension: '.test.js' }]),
      /Test root dist-missing is missing/,
    );
  });
});

