  return {
    white: game.white,
    black: game.black,
    result: game.result,
    ending: game.ending,
    moveCount: game.moves.length,
    hasClocks: clocked > 0,
    partialClocks: clocked > 0 && clocked < game.moves.length,
    includeInStats: game.includeInStats,
    ...(game.timeControl !== undefined ? { timeControl: game.timeControl } : {}),
  };
}

