// What: the shared sensing rules and the gaps in the drawn trace.
// Why: the screen and the coverage math must agree on what a hole is, or the strip would invent a pulse.
// Removed: a two-second dropout would be drawn as a smooth line.
import type { PulseSample } from './contracts.js';

/** Samples at or above this score can support a baseline or coverage. The raw file keeps the rest. */
export const CONFIDENCE_FLOOR = 50;
/** The resting pulse is the median of usable samples in this window. */
export const BASELINE_WINDOW_US = 60_000_000;
/** A usable sample covers the wait until the next one, and never more than this. */
export const SAMPLE_HOLD_US = 1_000_000;
/** The live quality reading looks back this far from the newest sample. */
export const SIGNAL_WINDOW_US = 60_000_000;
/** No sample for this long means the stream, not the lighting, is the problem. */
export const SIGNAL_STALE_MS = 5_000;
/** The session limit is enforced in main; this is the warning point for the screen. */
export const SESSION_WARNING_MS = 80 * 60 * 1_000;
export const SESSION_LIMIT_MS = 90 * 60 * 1_000;

export function isUsableSample(sample: PulseSample, floor = CONFIDENCE_FLOOR): boolean {
  return sample.stable && sample.confidence >= floor;
}

export type SignalQuality = 'waiting' | 'good' | 'weak' | 'poor';

export interface SignalReading {
  quality: SignalQuality;
  label: string;
  usable: number;
  total: number;
}

/**
 * The usable-sample share of the trailing minute. It looks back from the newest sample, because
 * the page has no separate monotonic clock shared with main. `signalStale` covers a stream that
 * has stopped; the ratio itself describes the samples that did arrive.
 */
export function signalQuality(samples: readonly PulseSample[], windowUs = SIGNAL_WINDOW_US): SignalReading {
  let latest = -Infinity;
  for (const sample of samples) {
    if (sample.tUs > latest) latest = sample.tUs;
  }
  if (!Number.isFinite(latest)) {
    return { quality: 'waiting', label: 'Waiting for samples', usable: 0, total: 0 };
  }
  const recent = samples.filter((sample) => latest - sample.tUs <= windowUs);
  if (recent.length === 0) {
    return { quality: 'waiting', label: 'Waiting for samples', usable: 0, total: 0 };
  }
  const usable = recent.filter((sample) => isUsableSample(sample)).length;
  const ratio = usable / recent.length;
  if (ratio >= 0.8) {
    return { quality: 'good', label: 'Good signal', usable, total: recent.length };
  }
  if (ratio >= 0.5) {
    return { quality: 'weak', label: 'Weak signal — check lighting', usable, total: recent.length };
  }
  return { quality: 'poor', label: 'Poor signal — check lighting and framing', usable, total: recent.length };
}

/** True when the stream has gone quiet, even if the last minute of stored samples looked good. */
export function signalStale(lastSampleAtMs: number | null, nowMs: number): boolean {
  return lastSampleAtMs !== null && nowMs - lastSampleAtMs > SIGNAL_STALE_MS;
}

/** Elapsed session time for the page. The stored header remains the authority for the report. */
export function formatElapsedMs(ms: number): string {
  const totalSeconds = Math.max(0, Math.floor(ms / 1_000));
  const hours = Math.floor(totalSeconds / 3_600);
  const minutes = Math.floor((totalSeconds % 3_600) / 60);
  const seconds = totalSeconds % 60;
  const two = (value: number): string => String(value).padStart(2, '0');
  return hours > 0 ? `${hours}:${two(minutes)}:${two(seconds)}` : `${minutes}:${two(seconds)}`;
}

/** Null before the warning point; a player-facing line at and after 80 minutes. */
export function limitWarning(elapsedMs: number): string | null {
  if (elapsedMs < SESSION_WARNING_MS) return null;
  const remaining = Math.max(0, SESSION_LIMIT_MS - elapsedMs);
  const minutes = Math.ceil(remaining / 60_000);
  if (minutes <= 0) return 'The 90-minute limit is reached. ChessPulse is stopping the session.';
  return `${minutes} ${minutes === 1 ? 'minute' : 'minutes'} left before the 90-minute limit.`;
}


export function traceSegments(
  samples: readonly PulseSample[],
  holdUs = SAMPLE_HOLD_US,
): PulseSample[][] {
  const ordered = [...samples].sort((left, right) => left.tUs - right.tUs);
  const segments: PulseSample[][] = [];
  let current: PulseSample[] = [];
  for (const sample of ordered) {
    const previous = current[current.length - 1];
    if (previous && sample.tUs - previous.tUs > holdUs) {
      segments.push(current);
      current = [];
    }
    current.push(sample);
  }
  if (current.length > 0) segments.push(current);
  return segments;
}
import {
  sessionEndedSchema,
  type SessionEndReason,
  type SessionEnded,
  type SessionMeta,
} from '../shared/contracts.js';
import type { SessionStopReason } from './session.js';

export interface SessionStopSeams {
  stopCapture(): Promise<SessionEndReason | undefined>;
  stopSession(reason: SessionStopReason): Promise<SessionMeta>;
  publish(event: SessionEnded): void;
}

export interface SessionStopper {
  beginSession(): void;
  stop(reason: SessionStopReason): Promise<SessionMeta>;
  active(): boolean;
}

const SESSION_ENDED_COPY: Record<SessionEndReason, string> = {
  storage: 'Sensing stopped because the pulse samples could not be saved. The session was closed.',
  limit: 'Sensing stopped at the 90-minute limit. The session was closed.',
};

// What: runs camera teardown, session finalization, and one automatic-ended publication as one operation.
// Why: concurrent user, SDK, storage, and limit stops must share one reason and one visible event.
// Removed: a second caller could finalize again or publish a different terminal reason.
export function createSessionStopper(seams: SessionStopSeams): SessionStopper {
  let inFlight: Promise<SessionMeta> | null = null;
  let pendingReason: SessionEndReason | undefined;
  // A finalized session whose automatic event still needs the page. A retry republishes this,
  // never finalizes again.
  let retained: { meta: SessionMeta; event: SessionEnded } | null = null;

  return {
    beginSession() {
      pendingReason = undefined;
      retained = null;
    },
    stop(reason) {
      if (inFlight) return inFlight;
      const run = (async () => {
        if (retained) {
          const { meta, event } = retained;
          seams.publish(event);
          retained = null;
          return meta;
        }
        const captureReason = await seams.stopCapture();
        const effectiveReason = captureReason ?? pendingReason ?? reason;
        if (effectiveReason === 'storage' || effectiveReason === 'limit') {
          pendingReason = effectiveReason;
        }
        const meta = await seams.stopSession(effectiveReason);
        pendingReason = undefined;
        if (effectiveReason === 'storage' || effectiveReason === 'limit') {
          const event = sessionEndedSchema.parse({
            sessionId: meta.id,
            reason: effectiveReason,
            message: SESSION_ENDED_COPY[effectiveReason],
          });
          // Retain until the page has actually received it; a throwing publish leaves this for retry.
          retained = { meta, event };
          seams.publish(event);
          retained = null;
        }
        return meta;
      })();
      inFlight = run.finally(() => {
        inFlight = null;
      });
      return inFlight;
    },
    active() {

    aiCheck(aiConfig),
  ];
  return {
    ok: checks.every((check) => check.status !== 'fail'),
    checks,
    lines: checks.map((check) => `${check.status.toUpperCase()} ${check.label}: ${check.detail}`),
  };
}

function nodeCheck(version: string): DoctorCheck {
  const major = Number.parseInt(version.split('.')[0] ?? '', 10);
  const ok = Number.isInteger(major) && major >= MIN_NODE_MAJOR;
  return {
    id: 'node',
    label: 'Node',
    status: ok ? 'pass' : 'fail',
    detail: `v${version} (needs ${MIN_NODE_MAJOR} or newer).`,
  };
}

function envCheck(envFile: EnvLoadResult): DoctorCheck {
  if (!envFile.found) {
    return {
      id: 'env',
      label: '.env',
      status: 'warn',
      detail: 'Not found. Values already in the shell environment are still used.',
    };
  }
  const names = [...new Set(envFile.loadedKeys)].sort();
  return {
    id: 'env',
    label: '.env',
    status: 'pass',
    detail:
      names.length > 0
        ? `Found. Loaded names only: ${names.join(', ')}.`
        : 'Found. No new settings were loaded.',
  };
}

function sensingKeyCheck(env: NodeJS.ProcessEnv): DoctorCheck {
  const present = readSensingKey(env).length > 0;
  return {
    id: 'sensing-key',
    label: 'SmartSpectra key',
    status: present ? 'pass' : 'fail',
    detail: present
      ? 'Present (value not shown).'
      : 'Missing. Set SMARTSPECTRA_API_KEY in .env or the environment.',
  };
}

function defaultCameraCheck(): DoctorCheck {
  return {
    id: 'camera',
    label: 'Camera',
    status: 'skip',
    detail: 'Enumeration runs inside the app window; Setup shows the live result.',
  };
}

export async function probeEngine(): Promise<DoctorCheck> {
  let engine: ReturnType<typeof createEngine> | undefined;
  try {
    engine = createEngine({ depth: 1, timeoutMs: 5_000, maxRestarts: 0 });
    const result = await engine.evaluate(START_FEN);
    if (result.evalFailed) {
      return {
        id: 'engine',
        label: 'Stockfish',
        status: 'fail',
        detail: `No usable answer (${result.reason ?? 'unknown'}).`,
      };
    }
    return {
      id: 'engine',
      label: 'Stockfish',
      status: 'pass',
      detail: 'Answered the UCI handshake and scored the start position.',
    };
// What: `npm run doctor` — prints the readiness checks a player or a support thread needs.
// Why: the same checks feed Setup and the diagnostics bundle, so the terminal cannot disagree.
// Removed: a broken install would be discovered only after a session.
import path from 'node:path';
import { runDoctor } from './doctor.js';
import { loadEnvFile } from './env.js';
import { defaultDataRoot } from './store.js';

export async function main(): Promise<number> {
  const envFile = process.env.CHESSPULSE_ENV_FILE ?? path.join(process.cwd(), '.env');
  const loaded = loadEnvFile(envFile, process.env);
  const report = await runDoctor({
    env: process.env,
    envFile: loaded,
    dataRoot: defaultDataRoot(),
  });
  process.stdout.write(`${report.lines.join('\n')}\n`);
  return report.ok ? 0 : 1;
}

if (process.argv[1] && path.resolve(process.argv[1]) === __filename) {
  main().then(
    (code) => process.exit(code),
    (error: unknown) => {
      const message = error instanceof Error ? error.message : 'The doctor could not run.';
      process.stderr.write(`${message}\n`);
      process.exit(1);
    },
  );
}

