  text = text.replace(/className="small-btn"/g, 'className="btn btn-quiet btn-small"');
  let out = '';
  let cursor = 0;
  while (true) {
    const start = text.indexOf('<button', cursor);
    if (start === -1) {
      out += text.slice(cursor);
      break;
    }
    out += text.slice(cursor, start);
    let index = start + '<button'.length;
    let depth = 0;
    let quote = null;
    for (; index < text.length; index += 1) {
      const character = text[index];
      if (quote) {
        if (character === quote && text[index - 1] !== '\\') quote = null;
        continue;
      }
      if (character === '"' || character === "'" || character === '`') {
        quote = character;
      } else if (character === '{') {
        depth += 1;
      } else if (character === '}') {
        depth -= 1;
      } else if (character === '>' && depth === 0) {
        break;
      }
    }
    let tag = text.slice(start, index + 1);
    if (!/className=/.test(tag)) {
      tag = tag.replace(/>$/, ' className="btn btn-secondary">');
    }
    out += tag;
    cursor = index + 1;
  }
  fs.writeFileSync(full, out);
}
