import { useEffect, useRef, useState } from 'react';
import type { AiProvider } from '../shared/contracts';
import { COPY } from './copy';

export type InsightViewState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'disabled'; reason: string }
  | { status: 'error'; message: string }
  | { status: 'ready'; text: string };

const PROVIDERS: { value: AiProvider; label: string }[] = [
  { value: 'openai', label: 'OpenAI' },
  { value: 'anthropic', label: 'Anthropic' },
  { value: 'google', label: 'Google' },
  { value: 'opencode', label: 'OpenCode' },
  { value: 'custom', label: 'Custom OpenAI-compatible' },
];

export function InsightPanel({
  state,
  onRequest,
  onCancel,
}: {
  state: InsightViewState;
  onRequest: (provider: AiProvider, text: string) => void;
  onCancel: () => void;
}) {
  const [provider, setProvider] = useState<AiProvider>('openai');
  const [question, setQuestion] = useState('What should I understand from this session?');
  const writeButton = useRef<HTMLButtonElement>(null);
  const cancelButton = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  const loading = state.status === 'loading';

  useEffect(() => {
    if (loading || !restoreFocus.current) return;
    restoreFocus.current = false;
    const active = document.activeElement;
    // Cancel's removal releases focus to the document. A different target means the user moved on.
    if (active !== document.body && active !== document.documentElement && active !== writeButton.current) return;
    writeButton.current?.focus();
  }, [loading]);

  const liveText =
    state.status === 'idle'
      ? 'Nothing is sent until you choose Write reading.'
      : state.status === 'loading'
        ? 'Writing from the computed report…'
        : state.status === 'disabled'
          ? state.reason
          : state.status === 'error'
            ? state.message
            : state.text;

  return (
    <section className="insight-panel" aria-labelledby="insight-title">
      <p className="label">{COPY.insight.label}</p>
      <h2 id="insight-title">Reading</h2>
      <p className="inferred-label">INFERRED — written by a model from the numbers above. Not measured.</p>

      <div className="insight-controls">
        <label>
          Provider
          <select value={provider} disabled={loading} onChange={(event) => setProvider(event.target.value as AiProvider)}>
            {PROVIDERS.map((item) => (
              <option key={item.value} value={item.value}>{item.label}</option>
            ))}
          </select>
        </label>
        <label>
          Question
          <textarea
            rows={3}
            maxLength={4000}
            value={question}
            disabled={loading}
            onChange={(event) => setQuestion(event.target.value)}
          />
        </label>
      </div>

      <div className="actions">
        <button ref={writeButton} type="button" disabled={loading || !question.trim()} onClick={() => onRequest(provider, question.trim())} className="btn btn-secondary">
          Write reading
        </button>
        {loading ? (
          <button
            ref={cancelButton}
            type="button"
            onClick={() => {
              restoreFocus.current = document.activeElement === cancelButton.current;
              onCancel();
            }}
           className="btn btn-secondary">
            Cancel
          </button>
        ) : null}
      </div>

      <p
        className={state.status === 'ready' ? 'insight-text' : state.status === 'error' ? 'insight-error' : 'insight-note'}
        role={state.status === 'error' ? 'alert' : undefined}
        aria-live="polite"
      >
        {liveText}
      </p>
    </section>
  );
}
// What: the camera preview, fed by the frames the main process already measures.
// Why: the player must see their own framing, and the page must not open a second camera stream.
// Removed: the player would be aiming blind, and a second stream would fight the SDK for the device.
import { useEffect, useRef, useState } from 'react';
import type { PreviewFrame } from '../shared/contracts';
import { lightNote, previewBoost } from '../shared/preview';

/** How long without a frame before the preview admits it is waiting. */
const STALE_MS = 2_000;
const LIGHT_UPDATE_MS = 500;

export function CameraPreview({ active, guide = false }: { active: boolean; guide?: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const lastFrameAt = useRef(0);
  const lastLightAt = useRef(0);
  const [light, setLight] = useState<number | null>(null);
  const [hasFrame, setHasFrame] = useState(false);
  const [stale, setStale] = useState(false);
  const bridge = window.chesspulse;

  useEffect(() => {
    if (!bridge) return undefined;
    return bridge.onPreview((frame: PreviewFrame) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const context = canvas.getContext('2d');
      if (!context) return;
      if (canvas.width !== frame.width) canvas.width = frame.width;
      if (canvas.height !== frame.height) canvas.height = frame.height;
      const pixels = new Uint8ClampedArray(frame.rgba.byteLength);
      pixels.set(frame.rgba);
      context.putImageData(new ImageData(pixels, frame.width, frame.height), 0, 0);
      lastFrameAt.current = Date.now();
      setHasFrame((current) => current || true);
      if (Date.now() - lastLightAt.current > LIGHT_UPDATE_MS) {
        lastLightAt.current = Date.now();
        setLight(frame.light);
      }
    });
  }, [bridge]);

  useEffect(() => {
    if (!active) {
      setStale(false);
      return undefined;
    }
    const timer = window.setInterval(() => {
      setStale(Date.now() - lastFrameAt.current > STALE_MS);
    }, 500);
    return () => window.clearInterval(timer);
  }, [active]);

  const boost = previewBoost(light);

  return (
    <figure className="camera">
      <div className="camera-frame">
        <canvas
          ref={canvasRef}
          className="camera-video"
          width={320}
          height={180}
          style={boost > 1 ? { filter: `brightness(${boost.toFixed(2)}) contrast(1.15)` } : undefined}
          role="img"
          aria-label="Camera preview. Nothing is recorded."
        />
        {guide ? (
          <div className="framing-guide" aria-hidden="true">
            <div className="face-outline" />
            <div className="chest-line" />
          </div>
        ) : null}
      </div>
      <figcaption className="hint">
        {!active
          ? 'The camera opens when you start sensing.'
          : !hasFrame || stale
            ? 'Waiting for the camera…'
            : lightNote(light)}
      </figcaption>
    </figure>
  );
}
import type { KeyboardEvent } from 'react';
import type { PulseSample } from '../shared/contracts';
import { BASELINE_WINDOW_US, traceSegments } from '../shared/sensing';

const Y_MIN = 40;
const Y_MAX = 180;
const WIDTH = 640;
const HEIGHT = 160;
const PAD = 16;

export function SensingStrip({
  samples,
  selectedIndex,
  onSelect,
}: {
  samples: PulseSample[];
  selectedIndex: number | null;
  onSelect: (index: number) => void;
}) {
  const ordered = [...samples].sort((left, right) => left.tUs - right.tUs);
  const latest = ordered[ordered.length - 1];
  const visible = latest
    ? ordered.filter((sample) => latest.tUs - sample.tUs <= BASELINE_WINDOW_US)
    : [];
  const shown = selectedIndex !== null ? samples[selectedIndex] : latest;
  const label = shown
    ? `${formatBpm(shown.bpm)} bpm, confidence ${shown.confidence}, ${shown.stable ? 'stable' : 'not stable'}`
    : 'Nothing recorded yet.';

  function onKey(event: KeyboardEvent<HTMLDivElement>): void {
    if (samples.length === 0) return;
    const current = selectedIndex ?? samples.length - 1;
    if (event.key === 'ArrowLeft') {
      event.preventDefault();
      onSelect(Math.max(0, current - 1));
    }
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      onSelect(Math.min(samples.length - 1, current + 1));
    }
  }

  return (
    <div
      className="strip"
      tabIndex={0}
      role="group"
      aria-roledescription="pulse trace"
      aria-label="Pulse trace"
      aria-describedby="strip-keys"
      onKeyDown={onKey}
    >
      <p id="strip-keys" className="hint">
        Left and right arrow keys move through samples.
      </p>
      <svg viewBox={`0 0 ${WIDTH} ${HEIGHT}`} role="presentation">
        <line className="axis" x1={PAD} y1={HEIGHT - PAD} x2={WIDTH - PAD} y2={HEIGHT - PAD} />
        {visible.length === 0 ? (
          <text className="empty" x={PAD} y={HEIGHT / 2}>
            Nothing recorded yet.
          </text>
        ) : (
          traceSegments(visible).map((segment) =>
            segment.length === 1 ? (
              <circle
                key={segment[0].tUs}
                cx={xOf(segment[0].tUs, visible)}
                cy={yOf(segment[0].bpm)}
                r={3}
              />
            ) : (
              <polyline key={segment[0].tUs} points={toPoints(segment, visible)} />
            ),
          )
        )}
        {shown && visible.some((sample) => sample.tUs === shown.tUs) ? (
          <circle cx={xOf(shown.tUs, visible)} cy={yOf(shown.bpm)} r={4} />
        ) : null}
      </svg>
      <p className="readout" aria-hidden="true">
        {shown ? formatBpm(shown.bpm) : '—'}
      </p>
      <p className="unit" aria-hidden="true">
        bpm
      </p>
      <p className="live" aria-live="polite">
        {label}
      </p>
    </div>
  );
}

function toPoints(segment: readonly PulseSample[], visible: readonly PulseSample[]): string {
  return segment.map((sample) => `${xOf(sample.tUs, visible).toFixed(1)},${yOf(sample.bpm).toFixed(1)}`).join(' ');
}

function xOf(tUs: number, visible: readonly PulseSample[]): number {
  const start = visible[0].tUs;
  const end = visible[visible.length - 1].tUs;
  if (end === start) return WIDTH / 2;
  return PAD + ((tUs - start) / (end - start)) * (WIDTH - PAD * 2);
}

function yOf(bpm: number): number {
  const clamped = Math.min(Y_MAX, Math.max(Y_MIN, bpm));
  return PAD + ((Y_MAX - clamped) / (Y_MAX - Y_MIN)) * (HEIGHT - PAD * 2);
}

function formatBpm(bpm: number): string {
  return Number.isInteger(bpm) ? String(bpm) : bpm.toFixed(1);
}

